scripts.script:
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Signal = ReplicatedStorage:WaitForChild("invisivel").OnClientEvent

task.spawn(function()
    while true do
        pcall(function()
            local args = {
                [1] = false
            }
            firesignal(Signal, unpack(args))
        end)
        task.wait(0.1) -- Adjust delay here
    end
end)
